-- ============================================================
-- ENUM TYPES
-- ============================================================
create type public.article_status as enum ('draft', 'published');
create type public.comment_status as enum ('pending', 'approved', 'hidden');
create type public.favorite_kind as enum ('listing', 'land');
create type public.inquiry_status as enum ('new', 'contacted', 'closed');
create type public.listing_submission_status as enum ('pending_review', 'published', 'rejected', 'deactivated');
create type public.listing_submission_type as enum ('mobilna', 'modularna', 'zemljisce');
create type public.payment_product_type as enum ('listing', 'plan', 'top_addon', 'homepage_addon');
create type public.payment_status as enum ('pending', 'paid', 'failed', 'cancelled', 'refunded');
create type public.user_role as enum ('user', 'dealer', 'admin');

-- ============================================================
-- FUNCTIONS
-- ============================================================
CREATE OR REPLACE FUNCTION public.prevent_role_self_escalation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.role <> old.role and auth.role() <> 'service_role' then
    new.role := old.role;
  end if;
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.handle_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  insert into public.profiles (id, full_name)
  values (new.id, new.raw_user_meta_data ->> 'full_name');
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.force_comment_pending()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.status := 'pending';
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.handle_new_user_subscription()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  insert into public.subscriptions (user_id, plan_id, status)
  values (new.id, 'free', 'active');
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$
;

