-- TABLES
-- ============================================================
create table public.admin_audit_log (
  id uuid default gen_random_uuid() not null,
  admin_id uuid not null,
  action text not null,
  entity_type text not null,
  entity_id text not null,
  before jsonb,
  after jsonb,
  created_at timestamp with time zone default now() not null,
  PRIMARY KEY (id)
);

create table public.articles (
  id uuid default gen_random_uuid() not null,
  slug text not null,
  title text not null,
  cover_image_url text,
  excerpt text not null,
  content text[] default '{}'::text[] not null,
  category text not null,
  author text default 'mobilnahiska.si'::text not null,
  seo_title text,
  seo_description text,
  status article_status default 'draft'::article_status not null,
  comments_enabled boolean default true not null,
  published_at timestamp with time zone,
  created_at timestamp with time zone default now() not null,
  updated_at timestamp with time zone default now() not null,
  PRIMARY KEY (id)
);

create table public.comments (
  id uuid default gen_random_uuid() not null,
  article_slug text not null,
  user_id uuid not null,
  content text not null,
  status comment_status default 'pending'::comment_status not null,
  created_at timestamp with time zone default now() not null,
  PRIMARY KEY (id)
);

create table public.email_log (
  id uuid default gen_random_uuid() not null,
  email_type text not null,
  recipient_email text not null,
  dedup_key text not null,
  user_id uuid,
  related_entity_type text,
  related_entity_id text,
  status text not null,
  created_at timestamp with time zone default now() not null,
  PRIMARY KEY (id)
);

create table public.favorites (
  id uuid default gen_random_uuid() not null,
  user_id uuid not null,
  kind favorite_kind not null,
  item_slug text not null,
  created_at timestamp with time zone default now() not null,
  PRIMARY KEY (id)
);

create table public.inquiries (
  id uuid default gen_random_uuid() not null,
  listing_slug text not null,
  listing_title text not null,
  listing_url text not null,
  seller_name text not null,
  user_id uuid,
  name text not null,
  email text not null,
  phone text,
  message text not null,
  status inquiry_status default 'new'::inquiry_status not null,
  created_at timestamp with time zone default now() not null,
