  location text not null,
  country text default 'Slovenija'::text not null,
  contact_name text not null,
  contact_phone text not null,
  contact_email text not null,
  condition text,
  manufacturer text,
  year integer,
  area numeric,
  length numeric,
  width numeric,
  bedrooms integer,
  bathrooms integer,
  capacity integer,
  delivery_available boolean,
  land_type text,
  utilities_available boolean,
  photo_urls text[] default '{}'::text[] not null,
  status listing_submission_status default 'pending_review'::listing_submission_status not null,
  created_at timestamp with time zone default now() not null,
  reviewed_at timestamp with time zone,
  reviewed_by uuid,
  rejection_reason text,
  expires_at timestamp with time zone,
  expiry_reminder_sent_at timestamp with time zone,
