alter table public.email_log add constraint email_log_status_check CHECK ((status = ANY (ARRAY['sent'::text, 'failed'::text, 'skipped_no_provider'::text])));
alter table public.email_log add constraint email_log_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE SET NULL;
alter table public.email_log add constraint email_log_dedup_key_key UNIQUE (dedup_key);
alter table public.favorites add constraint favorites_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;
