CREATE INDEX listing_submissions_top_idx ON public.listing_submissions USING btree (is_top) WHERE is_top;
CREATE INDEX listing_submissions_user_id_idx ON public.listing_submissions USING btree (user_id);
CREATE INDEX payments_created_at_idx ON public.payments USING btree (created_at DESC);
