CREATE UNIQUE INDEX payments_provider_transaction_id_idx ON public.payments USING btree (provider, provider_transaction_id) WHERE (provider_transaction_id IS NOT NULL);
CREATE INDEX payments_status_idx ON public.payments USING btree (status);
CREATE INDEX payments_user_id_idx ON public.payments USING btree (user_id);
CREATE UNIQUE INDEX profiles_provider_slug_idx ON public.profiles USING btree (provider_slug) WHERE (provider_slug IS NOT NULL);
CREATE INDEX rate_limit_hits_bucket_created_idx ON public.rate_limit_hits USING btree (bucket_key, created_at DESC);
CREATE UNIQUE INDEX subscriptions_provider_subscription_id_idx ON public.subscriptions USING btree (provider, provider_subscription_id) WHERE (provider_subscription_id IS NOT NULL);

