create policy "admin_audit_log_select_admin" on public.admin_audit_log for select to authenticated
  using ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = 'admin'::user_role)))));
create policy "articles_select_admin" on public.articles for select to authenticated
  using ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = 'admin'::user_role)))));
create policy "articles_select_published" on public.articles for select to anon,authenticated
  using ((status = 'published'::article_status));
create policy "comments_insert_own" on public.comments for insert to authenticated
  with check ((auth.uid() = user_id));
